// HPA de juguete: misma fórmula y mismos topes por defecto que la documentación, sin demoras de arranque.
const objetivo = 70, min = 2, max = 10, tolerancia = 0.1, ventanaBaja = 300, ciclo = 15;
let replicas = 2;
const recomendaciones = []; // [segundo, replicas recomendadas]
// carga medida en "Pods trabajando al 100 %": 1,2 de base; entre el segundo 60 y el 360 sube a 6,0
const carga = (s) => (s >= 60 && s < 360 ? 6.0 : 1.2);
console.log('seg | carga | uso% | recomienda | replicas');
for (let s = 0; s <= 780; s += ciclo) {
  const uso = (carga(s) / replicas) * 100;
  const razon = uso / objetivo;
  let reco = Math.abs(razon - 1) <= tolerancia ? replicas : Math.ceil(replicas * razon);
  reco = Math.min(max, Math.max(min, reco));
  recomendaciones.push([s, reco]);
  const antes = replicas;
  let nuevo = reco;
  if (reco > replicas) nuevo = Math.min(reco, replicas + Math.max(replicas, 4)); // tope de subida por ciclo
  if (reco < replicas) { // ventana de estabilización: se usa la mayor recomendación de los últimos 300 s
    nuevo = Math.max(...recomendaciones.filter(([t]) => s - t <= ventanaBaja).map(([, r]) => r));
    nuevo = Math.min(nuevo, replicas);
  }
  replicas = nuevo;
  if (replicas !== antes || s % 180 === 0) console.log(`${String(s).padStart(3)} | ${carga(s).toFixed(1).padStart(5)} | ${uso.toFixed(0).padStart(4)} | ${String(reco).padStart(10)} | ${replicas}`);
}
